QUESTIONS = {question_id: {"id": question_id, "section": section_id, "prompt": prompt}
             for section_id, _, _, items in SECTIONS for question_id, prompt in items}


def public_sections():
    return [{"id": section_id, "title": title, "scope": scope,
             "questions": [QUESTIONS[question_id] for question_id, _ in items]}
            for section_id, title, scope, items in SECTIONS]
